for(const name of ['execSync','exec','spawnSync','spawn','fork'])cp[name]=()=>{throw Error('Unapproved subprocess disabled: '+name);};
Module._extensions['.js']=(mod,filename)=>mod._compile(fs.readFileSync(filename,'utf8'),filename);
Module._extensions['.json']=(mod,filename)=>{mod.exports=JSON.parse(fs.readFileSync(filename,'utf8'));};
Module._extensions['.node']=()=>{throw Error('Native dependency outside approved candidate');};
const file=path.resolve(root,input.file),main=new Module(file,null);main.filename=file;main.paths=Module._nodeModulePaths(path.dirname(file));Module._cache[file]=main;process.mainModule=main;process.argv=[process.execPath,file];
